      var sh = Math.round(V.seed) || 1, rnd = ctx.kit.rng(ctx.seed + sh * 7919 >>> 0);
      var orbs = (ORBS[lay] || ORBS.title).map(function(o, i) {
        var x = o[0], y = o[1], r = o[2];
        if (sh > 1 && !o[4]) {
          var j = i ? 110 : 60;
          if (sh % 2 === 0) y = ctx.H - y;
          x += (rnd() - 0.5) * 2 * j;
          y += (rnd() - 0.5) * 2 * j;
          r *= 0.86 + rnd() * 0.3;
        }
        return {
          x,
          y,
          r: r * (o[4] ? 0.55 + V.size * 45e-4 : V.size / 100),
          kind: o[3],
          pin: !!o[4]
        };
      }).slice(0, Math.round(V.count));
